    long long a, b, c;
    cin >> a >> b >> c;

    // Let x = bonds between 1 and 2
    // Let y = bonds between 2 and 3
    // Let z = bonds between 3 and 1
    // Then:
    // x + z = a  (atom 1)
    // x + y = b  (atom 2)
    // y + z = c  (atom 3)

    // Solving:
    // x = (a + b - c) / 2
    // y = (b + c - a) / 2
    // z = (a + c - b) / 2

    long long sum = a + b + c;

    // Check if sum is even (since 2*(x+y+z) = a+b+c)
    if (sum % 2 != 0) {
        cout << "Impossible" << endl;
        return 0;
    }

    long long x = (a + b - c) / 2;
    long long y = (b + c - a) / 2;
    long long z = (a + c - b) / 2;

    // Check if all values are non-negative integers
    // Also need to verify that the values are integers (no fractional part)
    // Since we already checked sum is even, let's check if each expression is even

    if ((a + b - c) % 2 != 0 || (b + c - a) % 2 != 0 || (a + c - b) % 2 != 0) {
        cout << "Impossible" << endl;
        return 0;
    }

    if (x < 0 || y < 0 || z < 0) {
        cout << "Impossible" << endl;
        return 0;
    }

    // Verify the solution
    if (x + z == a && x + y == b && y + z == c) {
        cout << x << " " << y << " " << z << endl;
    } else {
        cout << "Impossible" << endl;
    }

    return 0;
}
